<?php
require_once __DIR__.'/../includes/auth.php'; require_role('superadmin','finance'); require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/lcc_payroll.php';
$error=''; $message='';
if($_SERVER['REQUEST_METHOD']==='POST') {
    require_csrf();
    try {
        $action=$_POST['action']??''; $conn->begin_transaction();
        if($action==='save') {
            $id=(int)($_POST['loan_id']??0); $employeeId=(int)($_POST['employee_id']??0); $typeId=(int)($_POST['loan_type_id']??0);
            $date=(string)($_POST['loan_date']??''); $start=(string)($_POST['repayment_start']??'');
            $principal=lcc_cents($_POST['principal']??''); $installment=lcc_cents($_POST['installment']??''); $term=(int)($_POST['term_periods']??0); $remarks=trim((string)($_POST['remarks']??''));
            if($employeeId<=0 || $typeId<=0 || !lcc_date($date) || !lcc_date($start) || $start<$date || $principal<=0 || $installment<=0 || $term<1 || $term>600 || $installment*$term<$principal || strlen($remarks)>255) throw new InvalidArgumentException('Enter a valid loan. The deduction per payroll must repay the amount within the selected number of payrolls.');
            $stmt=$conn->prepare("SELECT employee_id FROM employees WHERE employee_id=? AND employment_status<>'Archived'");$stmt->bind_param('i',$employeeId);$stmt->execute();
            if(!$stmt->get_result()->fetch_assoc()) throw new DomainException('Employee is not active.');
            $stmt=$conn->prepare('SELECT loan_type_id FROM loan_types WHERE loan_type_id=? AND is_active=1');$stmt->bind_param('i',$typeId);$stmt->execute();
            if(!$stmt->get_result()->fetch_assoc()) throw new DomainException('Loan type is inactive or missing.');
            $principalSql=lcc_decimal($principal); $installmentSql=lcc_decimal($installment);
            if($id>0) {
                $stmt=$conn->prepare('SELECT status FROM employee_loans WHERE loan_id=? FOR UPDATE');$stmt->bind_param('i',$id);$stmt->execute();$loan=$stmt->get_result()->fetch_assoc();
                if(!$loan || $loan['status']!=='Pending') throw new DomainException('Only Pending loans may be edited.');
                $stmt=$conn->prepare("UPDATE employee_loans SET employee_id=?,loan_type_id=?,loan_date=?,principal=?,installment=?,term_periods=?,repayment_start=?,remarks=? WHERE loan_id=? AND status='Pending'");
                $stmt->bind_param('iisssissi',$employeeId,$typeId,$date,$principalSql,$installmentSql,$term,$start,$remarks,$id);
            } else {
                $actor=(int)$_SESSION['admin_id'];
                $stmt=$conn->prepare("INSERT INTO employee_loans(employee_id,loan_type_id,loan_date,principal,installment,term_periods,repayment_start,remarks,created_by,status) VALUES(?,?,?,?,?,?,?,?,?,'Active')");
                $stmt->bind_param('iisssissi',$employeeId,$typeId,$date,$principalSql,$installmentSql,$term,$start,$remarks,$actor);
            }
            if(!$stmt->execute()) throw new RuntimeException('Could not save loan.');
            if(!$id)$id=$conn->insert_id;
            lcc_audit($conn,'loan_saved','loan',$id,'Principal '.$principalSql.'; installment '.$installmentSql.'; payrolls '.$term);
            $message='Loan saved. The scheduled deduction will be included in the next eligible payroll.';
        } elseif($action==='schedule') {
            $id=(int)($_POST['loan_id']??0); $installment=lcc_cents($_POST['installment']??''); $term=(int)($_POST['term_periods']??0);
            if($id<1 || $installment<1 || $term<1 || $term>600) throw new InvalidArgumentException('Enter a positive deduction and a valid number of payrolls.');
            $stmt=$conn->prepare("SELECT principal,status FROM employee_loans WHERE loan_id=? FOR UPDATE");$stmt->bind_param('i',$id);$stmt->execute();$loan=$stmt->get_result()->fetch_assoc();
            if(!$loan || $loan['status']!=='Active') throw new DomainException('Only active loans can change their future deduction schedule.');
            $stmt=$conn->prepare('SELECT COUNT(*) AS used FROM loan_repayments WHERE loan_id=?');$stmt->bind_param('i',$id);$stmt->execute();$used=(int)$stmt->get_result()->fetch_assoc()['used'];
            $stmt=$conn->prepare("SELECT COUNT(*) AS used,COALESCE(SUM(pl.amount),0) AS amount FROM payroll_lines pl JOIN payroll_records p ON p.payroll_id=pl.payroll_id WHERE pl.source_type='Loan' AND pl.source_id=? AND p.status='Approved'");$stmt->bind_param('i',$id);$stmt->execute();$reserved=$stmt->get_result()->fetch_assoc();
            $used+=(int)$reserved['used']; $balance=lcc_loan_balance($conn,$id,lcc_cents($loan['principal']))-lcc_cents($reserved['amount']);
            if($term<=$used || $installment*($term-$used)<$balance) throw new DomainException('The new schedule must cover the remaining balance after completed and approved deductions.');
            $amountSql=lcc_decimal($installment);
            $stmt=$conn->prepare('UPDATE employee_loans SET installment=?,term_periods=? WHERE loan_id=?');$stmt->bind_param('sii',$amountSql,$term,$id);
            if(!$stmt->execute()) throw new RuntimeException('Could not update the loan schedule.');
            lcc_audit($conn,'loan_schedule_changed','loan',$id,'Installment '.$amountSql.'; payrolls '.$term);
            $message='Future loan deductions updated.';
        } elseif($action==='status') {
            $id=(int)($_POST['loan_id']??0); $target=(string)($_POST['status']??'');
            $stmt=$conn->prepare('SELECT principal,status FROM employee_loans WHERE loan_id=? FOR UPDATE');$stmt->bind_param('i',$id);$stmt->execute();$loan=$stmt->get_result()->fetch_assoc();
            if(!$loan) throw new DomainException('Loan not found.');
            $allowed=['Pending'=>['Active','Cancelled'],'Active'=>['Suspended'],'Suspended'=>['Active','Cancelled']];
            if(!in_array($target,$allowed[$loan['status']]??[],true)) throw new DomainException('Invalid loan status transition.');
            $stmt=$conn->prepare("SELECT COUNT(*) AS total FROM payroll_lines l JOIN payroll_records p ON p.payroll_id=l.payroll_id WHERE l.source_type='Loan' AND l.source_id=? AND p.status='Approved'");
            $stmt->bind_param('i',$id);$stmt->execute();
            if((int)$stmt->get_result()->fetch_assoc()['total']>0) throw new DomainException('An Approved payroll contains this loan. Pay it or resolve the payroll first.');
            if($target==='Cancelled' && lcc_loan_balance($conn,$id,lcc_cents($loan['principal']))!==lcc_cents($loan['principal'])) throw new DomainException('Loans with posted repayments cannot be cancelled.');
            $stmt=$conn->prepare('UPDATE employee_loans SET status=? WHERE loan_id=?');$stmt->bind_param('si',$target,$id);
            if(!$stmt->execute()) throw new RuntimeException('Could not change loan status.');
            $stale=$conn->prepare("UPDATE payroll_records p JOIN payroll_periods pp ON pp.period_id=p.period_id JOIN employee_loans l ON l.employee_id=p.employee_id SET p.needs_recalculation=1 WHERE l.loan_id=? AND p.status='Draft' AND p.compensation_basis_snapshot='per_period' AND pp.pay_date>=l.repayment_start");
            $stale->bind_param('i',$id);$stale->execute();
            lcc_audit($conn,'loan_status_changed','loan',$id,$loan['status'].' to '.$target);
            $message='Loan status updated. Regenerate any affected Draft payroll.';
        } else throw new InvalidArgumentException('Unknown loan action.');
        $conn->commit();
    } catch(Throwable $e) { $conn->rollback(); $error=$e->getMessage(); }
}
$search=trim((string)($_GET['search']??''));$status=(string)($_GET['status']??'');
if(!in_array($status,['','Pending','Active','Suspended','Completed','Cancelled'],true))$status='';
$like='%'.$search.'%';
$stmt=$conn->prepare("SELECT l.*,t.name AS type_name,e.employee_no,e.first_name,e.last_name,COALESCE(SUM(r.amount),0) AS repaid,COUNT(r.repayment_id) AS installments_paid FROM employee_loans l JOIN loan_types t ON t.loan_type_id=l.loan_type_id JOIN employees e ON e.employee_id=l.employee_id LEFT JOIN loan_repayments r ON r.loan_id=l.loan_id WHERE (?='' OR CONCAT(e.first_name,' ',e.last_name) LIKE ? OR e.employee_no LIKE ?) AND (?='' OR l.status=?) GROUP BY l.loan_id ORDER BY l.loan_id DESC");
$stmt->bind_param('sssss',$search,$like,$like,$status,$status);$stmt->execute();$loans=$stmt->get_result();
$edit=null;$editId=(int)($_GET['edit']??0);
if($editId>0){$stmt=$conn->prepare("SELECT * FROM employee_loans WHERE loan_id=? AND status='Pending'");$stmt->bind_param('i',$editId);$stmt->execute();$edit=$stmt->get_result()->fetch_assoc();}
$schedule=null;$scheduleId=(int)($_GET['schedule']??0);
if($scheduleId>0){$stmt=$conn->prepare("SELECT l.*,t.name AS type_name,e.first_name,e.last_name FROM employee_loans l JOIN loan_types t ON t.loan_type_id=l.loan_type_id JOIN employees e ON e.employee_id=l.employee_id WHERE l.loan_id=? AND l.status='Active'");$stmt->bind_param('i',$scheduleId);$stmt->execute();$schedule=$stmt->get_result()->fetch_assoc();}
$employees=$conn->query("SELECT employee_id,employee_no,first_name,last_name FROM employees WHERE employment_status<>'Archived' ORDER BY last_name,first_name");
$types=$conn->query('SELECT loan_type_id,name FROM loan_types WHERE is_active=1 ORDER BY name');
$detailId=(int)($_GET['id']??0);$repayments=null;
if($detailId>0){$stmt=$conn->prepare('SELECT r.amount,r.posted_at,r.payroll_id,p.period_start,p.period_end FROM loan_repayments r JOIN payroll_records p ON p.payroll_id=r.payroll_id WHERE r.loan_id=? ORDER BY r.repayment_id');$stmt->bind_param('i',$detailId);$stmt->execute();$repayments=$stmt->get_result();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../assets/favicon.png"><title>LCC Payroll System</title><link rel="stylesheet" href="../assets/css/app.css?v=20261012-nav1"><link rel="stylesheet" href="../assets/css/apple-system.css?v=20261012-ux1"><script src="../assets/js/app.js?v=20261012-nav1" defer></script></head><body class="lcc-ux"><div class="app"><?php sidebar('loans'); ?><main class="main"><?php topbar('Employee Loans'); ?><div class="content"><div class="page-heading"><div><div class="eyebrow">LOAN MANAGEMENT</div><h1>Employee Loans</h1><p>Loan installments are deducted automatically when you add payroll. Balances change only when payment is recorded.</p></div><a class="btn btn-secondary" href="loan_types.php">Loan Types</a></div><div class="lcc-help-strip"><div><strong>How loans work</strong>Set the amount per payroll and the number of payroll deductions. The loan starts automatically on its repayment start date.</div><a href="getting_started.php">See all steps →</a></div><?php if($error): ?><div class="notice err"><?php echo e($error); ?></div><?php endif; ?><?php if($message): ?><div class="notice ok"><?php echo e($message); ?></div><?php endif; ?><section class="card form-card"><div class="card-head"><div><h2><?php echo $edit?'Edit Pending Loan':'Register Loan'; ?></h2></div></div><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="action" value="save"><input type="hidden" name="loan_id" value="<?php echo (int)($edit['loan_id']??0); ?>"><div class="form-body"><div class="form-grid"><div class="field"><label>Employee</label><select name="employee_id" required><option value="">Select employee</option><?php while($row=$employees->fetch_assoc()): ?><option value="<?php echo (int)$row['employee_id']; ?>" <?php echo (int)($edit['employee_id']??0)===(int)$row['employee_id']?'selected':''; ?>><?php echo e($row['employee_no'].' · '.$row['last_name'].', '.$row['first_name']); ?></option><?php endwhile; ?></select></div><div class="field"><label>Loan Type</label><select name="loan_type_id" required><option value="">Select type</option><?php while($row=$types->fetch_assoc()): ?><option value="<?php echo (int)$row['loan_type_id']; ?>" <?php echo (int)($edit['loan_type_id']??0)===(int)$row['loan_type_id']?'selected':''; ?>><?php echo e($row['name']); ?></option><?php endwhile; ?></select></div><div class="field"><label>Loan Date</label><input type="date" name="loan_date" required value="<?php echo e($edit['loan_date']??''); ?>"></div><div class="field"><label>Repayment Start Date</label><input type="date" name="repayment_start" required value="<?php echo e($edit['repayment_start']??''); ?>"></div><div class="field"><label>Principal</label><input type="number" min="0.01" step="0.01" name="principal" required value="<?php echo e($edit['principal']??''); ?>"></div><div class="field"><label>Deduction Per Payroll</label><input type="number" min="0.01" step="0.01" name="installment" required value="<?php echo e($edit['installment']??''); ?>"></div><div class="field"><label>Number of Payroll Deductions</label><input type="number" min="1" max="600" step="1" name="term_periods" required value="<?php echo e($edit['term_periods']??''); ?>"><small>Example: 12 means up to 12 payroll deductions. The last one is capped at the remaining balance.</small></div><div class="field full"><label>Remarks</label><input name="remarks" maxlength="255" value="<?php echo e($edit['remarks']??''); ?>"></div></div></div><div class="form-actions"><button class="btn btn-primary">Save Loan</button><?php if($edit): ?><a class="btn btn-secondary" href="loans.php">Cancel</a><?php endif; ?></div></form></section>
<?php if($schedule): ?><section class="card form-card"><div class="card-head"><div><h2>Change future deduction · <?php echo e($schedule['type_name']); ?> loan</h2><p><?php echo e($schedule['last_name'].', '.$schedule['first_name']); ?>. Completed and approved payroll deductions remain unchanged.</p></div></div><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="action" value="schedule"><input type="hidden" name="loan_id" value="<?php echo (int)$schedule['loan_id']; ?>"><div class="form-body"><div class="form-grid"><div class="field"><label>Deduction per payroll</label><input type="number" min="0.01" step="0.01" name="installment" required value="<?php echo e($schedule['installment']); ?>"></div><div class="field"><label>Total number of payroll deductions</label><input type="number" min="1" max="600" name="term_periods" required value="<?php echo (int)$schedule['term_periods']; ?>"></div></div></div><div class="form-actions"><button class="btn btn-primary">Save schedule</button><a class="btn btn-secondary" href="loans.php">Cancel</a></div></form></section><?php endif; ?><section class="card"><div class="card-head"><div><h2>Loan Ledger</h2></div></div><form method="get" class="toolbar"><div><label>Employee</label><input name="search" value="<?php echo e($search); ?>"></div><div><label>Status</label><select name="status"><option value="">All</option><?php foreach(['Pending','Active','Suspended','Completed','Cancelled'] as $choice): ?><option value="<?php echo $choice; ?>" <?php echo $status===$choice?'selected':''; ?>><?php echo $choice; ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary">Filter</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Type</th><th>Principal</th><th>Repaid</th><th>Balance</th><th>Deduction / payroll</th><th>Duration</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$loans->num_rows): ?><tr><td colspan="9" class="empty">No loans found.</td></tr><?php else: while($row=$loans->fetch_assoc()): ?><tr><td><?php echo e($row['employee_no'].' · '.$row['last_name'].', '.$row['first_name']); ?></td><td><?php echo e($row['type_name']); ?></td><td><?php echo money($row['principal']); ?></td><td><?php echo money($row['repaid']); ?></td><td><strong><?php echo money(lcc_decimal(lcc_cents($row['principal'])-lcc_cents($row['repaid']))); ?></strong></td><td><?php echo money($row['installment']); ?></td><td><?php echo $row['term_periods'] ? (int)$row['installments_paid'].' / '.(int)$row['term_periods'].' payrolls' : 'Until repaid'; ?></td><td><span class="badge"><?php echo e($row['status']); ?></span></td><td><a class="btn btn-secondary btn-small" href="loans.php?id=<?php echo (int)$row['loan_id']; ?>">History</a><?php if($row['status']==='Active'): ?><a class="btn btn-secondary btn-small" href="loans.php?schedule=<?php echo (int)$row['loan_id']; ?>">Change schedule</a><?php endif; ?><?php if($row['status']==='Pending'): ?><a class="btn btn-secondary btn-small" href="loans.php?edit=<?php echo (int)$row['loan_id']; ?>">Edit</a><?php endif; ?><?php $actions=['Pending'=>['Active','Cancelled'],'Active'=>['Suspended'],'Suspended'=>['Active','Cancelled']]; foreach($actions[$row['status']]??[] as $target): ?><form method="post" style="display:inline"><?php echo csrf_field(); ?><input type="hidden" name="action" value="status"><input type="hidden" name="loan_id" value="<?php echo (int)$row['loan_id']; ?>"><input type="hidden" name="status" value="<?php echo $target; ?>"><button class="btn btn-secondary btn-small"><?php echo e($target); ?></button></form><?php endforeach; ?></td></tr><?php endwhile; endif; ?></tbody></table></div></section>
<?php if($repayments): ?><section class="card"><div class="card-head"><div><h2>Repayment History · Loan #<?php echo $detailId; ?></h2></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Payroll</th><th>Period</th><th>Amount</th><th>Posted</th></tr></thead><tbody><?php if(!$repayments->num_rows): ?><tr><td colspan="4" class="empty">No repayments posted.</td></tr><?php else: while($row=$repayments->fetch_assoc()): ?><tr><td>#<?php echo (int)$row['payroll_id']; ?></td><td><?php echo e($row['period_start'].' – '.$row['period_end']); ?></td><td><?php echo money($row['amount']); ?></td><td><?php echo e($row['posted_at']); ?></td></tr><?php endwhile; endif; ?></tbody></table></div></section><?php endif; ?></div></main></div></body></html>
